/** Qualifying-bets minimum by duration and category (spec §4.4). */
export function minQualifying(durationMin: number, category: "slots" | "tables"): number {
  const t = durationMin <= 15 ? [20, 10] : durationMin <= 60 ? [40, 15] : durationMin <= 360 ? [75, 25] : [100, 30];
  return category === "slots" ? t[0]! : t[1]!;
}

export function rebuyLimit(durationMin: number): number {
  return durationMin <= 60 ? 2 : 3;
}
